export const BODY: string = "\n<p>پرانے ونڈوز سافٹ ویئر سے BMP فائل اسی تصویر کی JPG سے بیس گنا زیادہ بھاری ہو سکتی ہے۔ اسے بدلنے میں ایک منٹ سے کم لگتا ہے، اور نتیجہ بھیجنا، اپ لوڈ کرنا اور محفوظ کرنا کہیں آسان ہو جاتا ہے۔</p>\n<p>شفافیت کی فکر نہیں ہے، کیونکہ BMP فائلیں غیر شفاف ہوتی ہیں، اور صرف فیصلہ کوالٹی ترتیب کا ہے۔</p>\n<p>یہ رہنما ہر مرحلہ بتاتا ہے، تاکہ آپ کی پہلی تبدیلی صاف نکلے۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: کیا چاہیے</h2>\n<p>آپ کو BMP فائلیں اور جدید براؤزر چاہیے۔ کروم، ایج، فائر فاکس اور سفاری سب کام کرتے ہیں، ڈیسک ٹاپ اور موبائل پر۔</p>\n<p>فائلیں اپنے کمپیوٹر پر تلاش کریں۔ وہ عام طور پر پرانے ونڈوز سافٹ ویئر، اسکینر یا BMP فارمیٹ میں محفوظ کرنے والے ڈیجیٹل کیمروں سے آتی ہیں۔</p>\n<p>جان لیں کہ JPG کس لیے ہیں۔ فارم زیادہ سے زیادہ فائل سائز مانگ سکتا ہے، جبکہ آرکائیو کو سب سے اونچی کوالٹی چاہیے ہوتی ہے۔ مقصد ہی ترتیبات طے کرتا ہے۔</p>\n<h2 id=\"step-1-open-tool\">مرحلہ 1: BMP سے JPG ٹول کھولیں</h2>\n<p>براؤزر میں <a href=\"/ur/bmp-ko-jpg-mein-convert-karein/\">BMP to JPG ٹول</a> کھولیں۔ یہ صفحہ ونڈوز، میک، لینکس، کروم او ایس، اینڈرائیڈ اور آئی او ایس پر کام کرتا ہے۔</p>\n<p>آپ کو اپ لوڈ والا حصہ، کوالٹی سلائیڈر اور بدلیں بٹن دکھائی دے گا۔ یہ تین کنٹرول ہی پورا کام ہیں۔</p>\n<p>اکاؤنٹ کی ضرورت نہیں ہے، اور کچھ بھی اپ لوڈ نہیں ہوتا۔ تبدیلی آپ کے آلے پر ہوتی ہے، جو کام کے اسکین اور ذاتی فائلوں کے لیے اہم ہے۔</p>\n<h2 id=\"step-2-upload\">مرحلہ 2: اپنی BMP فائلیں اپ لوڈ کریں</h2>\n<p>اپنی BMP فائلیں اپ لوڈ والے حصے پر گھسیٹ دیں، یا فائل پکر کھولنے کے لیے اس پر کلک کریں۔ بیچ کے لیے کئی فائلیں ایک ساتھ چن سکتے ہیں۔</p>\n<p>ہر فائل کارڈ کے طور پر دکھائی دیتی ہے، تھمب نیل، ابعاد اور سائز کے ساتھ۔ فوری نظر سے یقین ہو جاتا ہے کہ درست فائلیں لوڈ ہوئیں اور کوئی اضافی نہیں آئی۔</p>\n<p>پرانی 1-bit اور 8-bit BMP فائلیں معاون ہیں، جیسے معیاری 24-bit فائلیں۔ کنورٹر ہر قسم کے لیے پیلیٹ اور پکسل ڈیٹا پڑھتا ہے۔</p>\n<h2 id=\"step-3-quality\">مرحلہ 3: کوالٹی سلائیڈر طے کریں</h2>\n<p>اسکین شدہ دستاویزات کے لیے کوالٹی 85 سے 90 فیصد پر طے کریں۔ چھوٹی چھپائی پڑھنے کے قابل رہتی ہے، اور فائل پھر بھی نوے فیصد یا زیادہ چھوٹی ہو جاتی ہے۔</p>\n<p>اسکرین شاٹ کے لیے 85 فیصد بہترین نقطہ ہے۔ انٹرفیس صاف رہتا ہے، اور فائل BMP سائز کا ایک حصہ ہوتی ہے۔</p>\n<p>BMP کے طور پر محفوظ تصویروں کے لیے 80 سے 85 فیصد درست حد ہے۔ تصویر صاف لگتی ہے، اور فائل ڈرامائی طور پر چھوٹی ہو جاتی ہے۔</p>\n<h2 id=\"step-4-convert\">مرحلہ 4: فائلیں بدلیں</h2>\n<p>Convert بٹن پر کلک کریں۔ ٹول ہر BMP ڈی کوڈ کرتا ہے، اسے کینوس پر بناتا ہے اور JPG کے طور پر انکوڈ کرتا ہے۔</p>\n<p>تبدیلی تیز ہوتی ہے، عام طور پر فی فائل ایک یا دو سیکنڈ۔ بڑی فائلیں تھوڑا زیادہ وقت لیتی ہیں، کیونکہ انکوڈ کرنے کے لیے زیادہ پکسل ہوتے ہیں۔</p>\n<p>ہر کارڈ پرانی BMP سائز کے ساتھ نیا JPG سائز دکھا کر اپ ڈیٹ ہوتا ہے۔ اچھی تبدیلی زیادہ تر فائلوں پر نوے فیصد یا زیادہ بچت دکھاتی ہے۔</p>\n<h2 id=\"step-5-preview\">مرحلہ 5: ڈاؤن لوڈ سے پہلے پیش نظارہ دیکھیں</h2>\n<p>کسی بھی کارڈ پر Compare پر کلک کر کے BMP اور JPG ساتھ ساتھ دیکھیں۔ متن اور باریک تفصیل جانچنے کے لیے اسپلٹ ہینڈل تصویر پر گھسیٹیں۔</p>\n<p>سب سے چھوٹا متن پہلے جانچیں، کیونکہ یہ JPG کمپریشن سے سب سے زیادہ متاثر ہوتا ہے۔ 85 فیصد کوالٹی پر اسکین شدہ دستاویز کی چھپائی مکمل پڑھنے کے قابل رہنی چاہیے۔</p>\n<p>رنگ بھی دیکھیں۔ زیادہ تر BMP فائلیں اپنے رنگ درست رکھتی ہیں، اگرچہ غیر معمولی پیلیٹ تبدیلی کے دوران ہلکے بدل سکتے ہیں۔</p>\n<h2 id=\"step-6-download\">مرحلہ 6: JPG فائلیں ڈاؤن لوڈ کریں</h2>\n<p>ایک JPG محفوظ کرنے کے لیے کسی کارڈ پر Download پر کلک کریں۔ فائل نام آپ کا اصل نام .jpg ایکسٹینشن کے ساتھ رکھتا ہے۔</p>\n<p>بیچ کے لیے Download All پر کلک کر کے ایک ZIP لیں جس میں ہر بدلی ہوئی JPG ہو۔ یہ ایک ایک کر کے ڈاؤن لوڈ کرنے سے کہیں تیز ہے۔</p>\n<p>استعمال سے پہلے ڈاؤن لوڈ شدہ فائلیں ایک بار جانچیں۔ JPG اپنے فوٹو ویور میں کھولیں، یقین کریں کہ وہ درست لگتی ہے اور وہاں کھلتی ہے جہاں اسے کھلنا ہے۔</p>\n<ol>\n<li>BMP سے JPG ٹول کھولیں اور اپنی BMP فائلیں اپ لوڈ کریں۔</li>\n<li>کوالٹی سلائیڈر 85 فیصد پر طے کریں۔</li>\n<li>بدلیں اور Compare سے متن جانچیں۔</li>\n<li>اکیلی JPG ڈاؤن لوڈ کریں یا پورا بیچ ZIP کے طور پر ڈاؤن لوڈ کریں۔</li>\n</ol>\n<h2 id=\"converting-a-folder\">BMP اسکین کا فولڈر بدلنا</h2>\n<p>فولڈر کی تمام BMP فائلیں ایک ساتھ چنیں۔ وہ قطار میں لوڈ ہو جاتی ہیں، اور ایک کلک سے سب JPG میں بدل جاتی ہیں۔</p>\n<p>پورے فولڈر کے لیے ایک ہی کوالٹی ترتیب استعمال کریں۔ مستقل مزاجی اہم ہے جب اسکین ایک ہی آرکائیو یا دستاویز سیٹ سے تعلق رکھتے ہوں۔</p>\n<p>بدلنے کے بعد بیچ خلاصہ دیکھیں۔ BMP اسکین کا فولڈر اکثر مجموعی طور پر پچانوے فیصد چھوٹا ہو جاتا ہے، جو ڈرامائی عدد ہے۔</p>\n<h2 id=\"fixing-problems\">عام مسائل کا حل</h2>\n<p>اگر BMP فائل بدلنے میں ناکام ہو تو اسے پہلے ونڈوز پینٹ میں کھول کر معیاری BMP کے طور پر دوبارہ محفوظ کریں۔ پرانے سافٹ ویئر کی غیر معمولی قسمیں کبھی غیر معاون خصوصیات استعمال کرتی ہیں۔</p>\n<p>اگر متن دھندلا لگے تو کوالٹی بہت کم تھی۔ سلائیڈر 90 فیصد پر بڑھائیں اور اصل BMP سے دوبارہ بدلیں۔</p>\n<p>اگر JPG BMP سے بمشکل چھوٹی ہو تو تصویر شاید بہت سادہ یا بہت شور والی ہے۔ سادہ تصویر میں کمپریس کرنے کو کچھ نہیں ہوتا، جبکہ شور کمپریشن کے خلاف مزاحمت کرتا ہے۔</p>\n<h2 id=\"after-converting\">بدلنے کے بعد: آگے کیا کریں</h2>\n<p>اگر JPG فارم کے لیے ہیں تو اپ لوڈ سے پہلے سائز حد جانچیں۔ 85 فیصد کوالٹی پر بدلی ہوئی JPG سخت حد سے پھر بھی اوپر ہو سکتی ہے، اور آپ کو اسے مزید کمپریس کرنا پڑ سکتا ہے۔</p>\n<p>جب پورٹل بالکل سائز مانگے تو <a href=\"/ur/tasveer-compress-karein-100kb-tak/\">100KB کمپریسر</a> یا <a href=\"/ur/makhsus-size-tak-tasveer-compress-karein/\">Target File Size Compressor</a> استعمال کریں۔ پہلے بدلیں، پھر کمپریس کریں، اسی ترتیب میں۔</p>\n<p>اگر JPG آرکائیو کے لیے ہیں تو انہیں صاف ناموں کے ساتھ محفوظ کریں۔ invoice-2024-03.jpg جیسا نام سالوں بعد مفید ہوتا ہے، جبکہ scan001.jpg جیسا نام نہیں ہوتا۔</p>\n<h2 id=\"mobile-tips\">فون اور ٹیبلٹ کے لیے نکات</h2>\n<p>فون پر اپ لوڈ والے حصے پر ٹیپ کریں اور اپنے آلے سے BMP فائلیں چنیں۔ تبدیلی فون پر چلتی ہے، اور JPG آپ کے آلے پر ڈاؤن لوڈ ہوتی ہیں۔</p>\n<p>فون کے بیچ چھوٹے رکھیں، کیونکہ بڑی BMP فائلیں موبائل پروسیسر پر انکوڈ ہونے میں وقت لیتی ہیں۔ ایک وقت میں دس فائلیں آرام دہ ہیں۔</p>\n<p>ڈاؤن لوڈ آپ کے فون کے Downloads فولڈر میں آتے ہیں۔ آئی فون پر Files ایپ جانچیں، اینڈرائیڈ پر اپنا فائل مینیجر جانچیں۔</p>\n<h2 id=\"scans-for-archive\">آرکائیو کے لیے اسکین بدلنا</h2>\n<p>اسکین شدہ دستاویزات کا آرکائیو عام BMP مجموعہ ہے۔ BMP کے طور پر محفوظ سینکڑوں صفحے ڈرائیو بھر دیتے ہیں، جبکہ وہی صفحے JPG کے طور پر جگہ کے ایک حصے میں فٹ ہو جاتے ہیں۔</p>\n<p>اسکین کو پچاس کے بیچ میں بدلیں، 85 سے 90 فیصد کوالٹی استعمال کرتے ہوئے۔ متن پڑھنے کے قابل رہتا ہے، فائلیں پچانوے فیصد چھوٹی ہو جاتی ہیں اور آرکائیو قابل انتظام بن جاتا ہے۔</p>\n<p>بدلنے سے پہلے اسکین کو سال یا موضوع کے حساب سے ترتیب دیں۔ ترتیب شدہ آرکائیو میں گھومنا آسان ہے، جبکہ ہزار فائلوں والا ایک فولڈر نہیں ہے۔</p>\n<h2 id=\"bmp-for-email\">ای میل کے لیے BMP بدلنا</h2>\n<p>ای میل منسلکات کی سائز حد ہوتی ہے، عام طور پر 20 MB سے 25 MB، اور ایک BMP اسکین اس سے اوپر جا سکتا ہے۔ پہلے JPG میں بدلنے سے ای میل حد سے نیچے رہتا ہے۔</p>\n<p>ایک اسکین کے لیے اسے 85 فیصد کوالٹی پر JPG میں بدلیں اور نتیجہ منسلک کریں۔ فائل BMP سائز کا ایک حصہ ہوتی ہے، اور وصول کنندہ وہی دستاویز دیکھتا ہے۔</p>\n<p>کئی اسکین کے لیے بیچ بدلیں اور JPG ایک ساتھ منسلک کریں۔ پانچ BMP اسکین کا سیٹ 50 MB ہو سکتا ہے، جبکہ JPG نسخے کل 2 MB ہوتے ہیں۔</p>\n<h2 id=\"bmp-for-form\">فارم کے لیے BMP بدلنا</h2>\n<p>اپ لوڈ فارم قبول شدہ فارمیٹ کے طور پر JPG اور PNG لکھتے ہیں، اور BMP فائل سیدھا واپس آ جاتی ہے۔ اپ لوڈ سے پہلے JPG میں بدلیں، اور پہلے فارم کے اصول جانچیں۔</p>\n<p>تصویر کو 85 فیصد کوالٹی پر JPG میں بدلیں۔ دستاویز صاف لگتی ہے، فائل معقول سائز کی ہوتی ہے اور فارم اسے بغیر کسی مشکل کے قبول کر لیتا ہے۔</p>\n<p>بدلنے کے بعد فائل سائز حد جانچیں۔ 2 MB تک اپ لوڈ دینے والا فارم 4 MB JPG مسترد کر سکتا ہے، اور آپ کو 100KB یا 200KB ٹول سے کمپریس کرنا پڑ سکتا ہے۔</p>\n<h2 id=\"bmp-for-website\">ویب سائٹ کے لیے BMP بدلنا</h2>\n<p>ویب سائٹس شاذ ہی BMP اپ لوڈ قبول کرتی ہیں، اور ویب صفحے پر BMP تصویر آہستہ کھلتی ہے۔ اپ لوڈ سے پہلے JPG میں بدلیں، اور صفحہ درست کام کرتا ہے۔</p>\n<p>ویب کے لیے BMP کو 80 سے 85 فیصد کوالٹی پر JPG میں بدلیں۔ تصویر صاف لگتی ہے، فائل چھوٹی ہوتی ہے اور صفحہ ہر وزیٹر کے لیے جلد کھلتا ہے۔</p>\n<p>متن والی ویب سائٹ تصویر کے لیے WebP پر غور کریں۔ اسی سائز پر متن JPG سے تیز رہتا ہے، جو اسکرین شاٹ اور ڈایاگرام کے لیے اہم ہے۔</p>\n<h2 id=\"folder-of-old-files\">پرانی فائلوں کا فولڈر بدلنا</h2>\n<p>شیئر شدہ ڈرائیو پر BMP فائلوں کا پرانا فولڈر عام دریافت ہے۔ سینکڑوں بھولے ہوئے اسکین اور اسکرین شاٹ، ہر ایک کئی میگا بائٹ، بغیر وجہ جگہ بھر رہے ہوتے ہیں۔</p>\n<p>پہلے فولڈر ترتیب دیں، نقل اور غیر ضروری فائلیں ہٹا دیں۔ پانچ سو فائلوں والے فولڈر میں اکثر سو رکھنے کے قابل ہوتی ہیں، اور صرف انہیں بدلنے سے حقیقی وقت بچتا ہے۔</p>\n<p>رکھنے والی فائلیں پچاس کے بیچ میں بدلیں، 85 فیصد کوالٹی استعمال کرتے ہوئے۔ ہر بیچ ہموار چلتا ہے، اور ایک بیچ کی ناکامی دوسروں کو متاثر نہیں کرتی۔</p>\n<h2 id=\"bmp-for-school-project\">اسکول پراجیکٹ کے لیے BMP بدلنا</h2>\n<p>اسکول پراجیکٹ کو اکثر پرانے سافٹ ویئر سے تصویریں چاہییں ہوتی ہیں، اور وہ تصویریں عام طور پر BMP ہوتی ہیں۔ پرانے سافٹ ویئر والا اسکول کمپیوٹر انہیں دکھا سکتا ہے، مگر پراجیکٹ فائل بہت بڑی ہو جاتی ہے۔</p>\n<p>پراجیکٹ میں شامل کرنے سے پہلے BMP تصویروں کو JPG میں بدلیں۔ JPG پاورپوائنٹ، ورڈ اور گوگل سلائیڈز میں صاف ایمبیڈ ہوتی ہیں، اور پراجیکٹ فائل قابل انتظام رہتی ہے۔</p>\n<p>کئی تصویروں والے پراجیکٹ کے لیے پورا سیٹ ایک ساتھ بدلیں۔ بیچ تبدیلی میں منٹ لگتے ہیں، اور JPG سلائیڈوں میں ڈالنے کے لیے تیار ہوتی ہیں۔</p>\n<p>پورا طریقہ یہی ہے: اپ لوڈ کریں، کوالٹی طے کریں، بدلیں، ڈاؤن لوڈ کریں۔ پس منظر کے لیے <a href=\"/ur/blog/bmp-ko-jpg-rehnumai/\">BMP to JPG: Complete Guide</a> پڑھیں، اور سائز سوال کے لیے <a href=\"/ur/blog/bmp-vs-jpg-file-size/\">BMP vs JPG: Why BMP Files Are So Large</a> دیکھیں۔ اگر آپ کو PNG چاہیے تو <a href=\"/ur/tasveer-convert-karein/\">Image Converter</a> BMP سے PNG بھی سنبھالتا ہے۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"BMP اسکین سے بھرا فولڈر بیچ میں کیسے بدلوں؟","answer":"فائل پکر میں فولڈر کی تمام BMP فائلیں ایک ساتھ چنیں، یا فولڈر کو اپ لوڈ والے حصے پر گھسیٹ دیں۔ کوالٹی 85 فیصد پر طے کریں، بدلیں اور ZIP ڈاؤن لوڈ کریں۔ تازہ فولڈر میں نکالیں تاکہ بدلی ہوئی JPG اصل BMP کو کبھی اوور رائٹ نہ کریں۔"},{"question":"کیا صفحہ کھلنے کے بعد انٹرنیٹ کے بغیر BMP فائلیں بدل سکتا ہوں؟","answer":"جی ہاں۔ صفحہ لوڈ ہونے کے بعد تبدیلی آپ کے براؤزر میں مقامی طور پر چلتی ہے اور انٹرنیٹ کی ضرورت نہیں ہوتی۔ آپ کو کنکشن صرف پہلی بار صفحہ کھولنے کے لیے چاہیے ہوتا ہے۔ اس کے بعد آپ ٹیب بند کرنے تک BMP فائلیں آف لائن بدل سکتے ہیں۔"},{"question":"کیا JPG کسی بھی پروگرام میں کھلے گی؟","answer":"جی ہاں۔ JPG موجود سب سے مطابقت پذیر امیج فارمیٹ ہے، اور یہ ونڈوز فوٹوز، میک او ایس پری ویو، واٹس ایپ، پرانے پرنٹر اور ہر براؤزر اور ایڈیٹر میں کھلتی ہے۔ بدلی ہوئی JPG خاص تقاضوں کے بغیر معیاری فائل ہوتی ہے۔"},{"question":"کیا پہلی تبدیلی کے بعد کوالٹی سلائیڈر بدل سکتا ہوں؟","answer":"جی ہاں۔ اصل BMP فائلیں پہلی تبدیلی کے بعد قطار میں رہتی ہیں، اس لیے آپ کوالٹی سلائیڈر ہلا کر دوبارہ اپ لوڈ کیے بغیر دوبارہ بدل سکتے ہیں۔ ترتیبات بدلنے سے پہلے ہر نسخہ ڈاؤن لوڈ کریں، کیونکہ ڈاؤن لوڈ بٹن موجودہ تبدیلی محفوظ کرتا ہے۔"},{"question":"کیا BMP سے JPG موبائل براؤزر پر کام کرتا ہے؟","answer":"جی ہاں۔ اپنے فون کے براؤزر میں ٹول کھولیں، اپنے آلے سے BMP فائلیں چنیں اور JPG ڈاؤن لوڈ کریں۔ تبدیلی فون پر چلتی ہے، اور فائلیں آپ کے آلے پر ڈاؤن لوڈ ہوتی ہیں۔ فون کے بیچ چھوٹے رکھیں، کیونکہ بڑی BMP فائلیں موبائل پر انکوڈ ہونے میں وقت لیتی ہیں۔"},{"question":"اگر BMP فائل بدلنے میں ناکام ہو تو کیا کروں؟","answer":"اسے پہلے ونڈوز پینٹ میں کھولیں اور معیاری BMP کے طور پر دوبارہ محفوظ کریں۔ پرانے سافٹ ویئر کی غیر معمولی قسمیں کبھی غیر معاون کمپریشن یا رنگ گہرائی استعمال کرتی ہیں۔ اگر فائل پھر بھی ناکام ہو تو جانچیں کہ یہ واقعی BMP ہے، .bmp ایکسٹینشن والا کوئی دوسرا فارمیٹ نہیں۔"}];
